import React from "react";

/**
 * VigletLogo: product mark.
 *
 * Each product is an isometric cube in its colour, its front-top corner cut in the
 * angle of the Viglet V, with the element symbol (Du / Sh / Tu) on its left face.
 * The SVGs in static/img/logos/ are generated by make_marks.py in the
 * alegauss/visibility repository (marca/logo/), where the geometry is documented;
 * copy them over after regenerating, do not edit them by hand.
 *
 * Below 56 px the cube is drawn without the symbol, which stops reading there.
 */

export const PRODUCT_COLORS: Record<string, string> = {
  dumont: "#0F766E",
  shio: "#7C3AED",
  turing: "#4169E1",
};

const PRODUCT_NAMES: Record<string, string> = {
  dumont: "Viglet Dumont",
  shio: "Viglet Shio",
  turing: "Viglet Turing",
};

interface VigletLogoProps {
  product: string;
  size?: number;
  /** A slow, soft light around the cube at hero sizes. */
  glow?: boolean;
  className?: string;
}

export default function VigletLogo({ product, size = 48, glow = true, className }: VigletLogoProps): React.ReactElement | null {
  const name = PRODUCT_NAMES[product];
  if (!name) return null;
  const small = size < 56;
  const classes = [className, glow && !small ? "vg-cube-glow" : ""].filter(Boolean).join(" ");
  return (
    <img
      src={`/img/logos/${product}${small ? "-small" : ""}.svg`}
      alt={name}
      width={size}
      height={size}
      className={classes || undefined}
      style={{ flexShrink: 0, userSelect: "none" }}
      draggable={false}
    />
  );
}
